"use client";
import type { ReactElement, ReactNode } from "react";
import { cloneElement, isValidElement, useEffect, useId, useRef, useState } from "react";
import "./tooltip.css";

/** A small label that appears on hover or keyboard focus, wired with aria-describedby. Escape closes it. */
export function Tooltip({
  content,
  children,
  side = "top",
  delay = 250,
}: {
  content: ReactNode;
  children: ReactElement<{ "aria-describedby"?: string }>;
  side?: "top" | "bottom";
  delay?: number;
}) {
  const id = useId();
  const [open, setOpen] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  const show = (wait: number) => {
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setOpen(true), wait);
  };
  const hide = () => {
    clearTimeout(timer.current);
    setOpen(false);
  };
  return (
    <span
      className="forme-tooltip"
      data-side={side}
      onPointerEnter={() => show(delay)}
      onPointerLeave={hide}
      onFocus={() => show(0)}
      onBlur={hide}
      onKeyDown={(e) => e.key === "Escape" && hide()}
    >
      {isValidElement(children) ? cloneElement(children, { "aria-describedby": id }) : children}
      <span role="tooltip" id={id} className="forme-tooltip-bubble" data-open={open || undefined}>
        {content}
      </span>
    </span>
  );
}

.forme-tooltip {
  position: relative;
  display: inline-flex;
}
.forme-tooltip-bubble {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 8px);
  z-index: 50;
  width: max-content;
  max-width: 240px;
  padding: 6px 10px;
  border-radius: 8px;
  background: #18181b;
  box-shadow:
    inset 0 0 0 1px #ffffff1f,
    0 8px 24px -8px #0008;
  color: #fafafa;
  font-size: 12.5px;
  font-weight: 500;
  line-height: 1.4;
  text-align: center;
  opacity: 0;
  visibility: hidden;
  transform: translate(-50%, 4px) scale(0.96);
  transform-origin: bottom center;
  transition:
    opacity 0.15s,
    transform 0.15s,
    visibility 0.15s;
  pointer-events: none;
}
.forme-tooltip[data-side="bottom"] .forme-tooltip-bubble {
  top: calc(100% + 8px);
  bottom: auto;
  transform: translate(-50%, -4px) scale(0.96);
  transform-origin: top center;
}
.forme-tooltip-bubble[data-open] {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0) scale(1);
}
.forme-tooltip[data-side="bottom"] .forme-tooltip-bubble[data-open] {
  transform: translate(-50%, 0) scale(1);
}
@media (prefers-reduced-motion: reduce) {
  .forme-tooltip-bubble {
    transition: none;
  }
}
